<script setup lang="ts">
definePageMeta({ layout: 'auth' })
const route = useRoute(); const { request } = useApiClient(); const token = ref(typeof route.query.token === 'string' ? route.query.token : ''); const password = ref(''); const message = ref(''); const busy = ref(false)
async function submit() { busy.value = true; message.value = ''; try { await request('/api/profile/password-reset', { method: 'POST', body: { token: token.value.trim(), newPassword: password.value } }); await navigateTo('/login') } catch (cause) { message.value = cause instanceof Error ? cause.message : 'รีเซ็ตรหัสผ่านไม่สำเร็จ' } finally { busy.value = false } }
</script>
<template><form class="w-full max-w-md space-y-4 rounded-xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900" @submit.prevent="submit"><h1 class="text-xl font-semibold">ตั้งรหัสผ่านใหม่</h1><input v-model="token" required minlength="32" placeholder="Reset Token" class="min-h-11 w-full rounded-lg border border-slate-300 bg-transparent px-3 dark:border-slate-700"><input v-model="password" required minlength="12" type="password" autocomplete="new-password" placeholder="รหัสผ่านใหม่" class="min-h-11 w-full rounded-lg border border-slate-300 bg-transparent px-3 dark:border-slate-700"><p v-if="message" role="alert" class="text-sm text-rose-600">{{ message }}</p><UButton type="submit" block :loading="busy" label="บันทึกรหัสผ่าน" /></form></template>
